root = Path(__file__).resolve().parents[1] / 'app/src/main/res'
for folder, index in [('values',0),('values-zh-rHK',0),('values-en',1)]:
    target = root / folder / 'strings.xml'
    target.parent.mkdir(parents=True,exist_ok=True)
    rows = [f'    <string name="{key}">{escape(pair[index]).replace(chr(39), chr(92)+chr(39)).replace(chr(10), chr(92)+"n")}</string>' for key,pair in COPY.items()]
    target.write_text('<?xml version="1.0" encoding="utf-8"?>\n<resources>\n'+'\n'.join(rows)+'\n</resources>\n',encoding='utf-8')
print(f'Generated {len(COPY)} keys for three catalogs')
